use crate::legacy_trig::{pi_fixed, TrigError};
use crate::IBig;

pub const MIN_FIXED_PRECISION_BITS: u32 = 8;
pub const MAX_FIXED_PRECISION_BITS: u32 = 400;
pub const ANCHOR_COUNT: u32 = 403;
pub const ANCHOR_SOURCE_PRECISION_BITS: u32 = 410;
pub const ANCHOR_CACHE_PRECISION_BITS: u32 = 400;
pub const ANCHOR_SOURCE_SHA256: &str =
    "8e80593f814e7713df89e5aca352cfb52afa747c9da46fcb42217f6d841858c8";
pub const ANCHOR_GENERATION_TEXT_SHA256: &str =
    "519f2ba0b3a61d034919ef4adfe8d7f19948d154d121eabd096186727e51623b";

/// Внутренние границы finite-прототипа, не admission/refusal Density.
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum UnsupportedProfile {
    Precision {
        requested: u32,
        minimum: u32,
        maximum: u32,
    },
    ReducedArgument {
        requested: IBig,
        minimum: IBig,
        maximum: IBig,
        bits: u32,
    },
    AnchorIndex {
        requested: u32,
        count: u32,
    },
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub enum BasecaseError {
    UnsupportedProfile(UnsupportedProfile),
    Pi(TrigError),
}

pub type BasecaseResult<T> = Result<T, BasecaseError>;

/// Неизменяемая actual-пара при P=400; sqrt на runtime-пути не выполняется.
pub fn anchor(index: u32) -> BasecaseResult<(IBig, IBig)> {
    let Some(&(cos, sin)) = ANCHORS.get(index as usize) else {
        return Err(BasecaseError::UnsupportedProfile(
            UnsupportedProfile::AnchorIndex {
                requested: index,
                count: ANCHOR_COUNT,
            },
        ));
    };
    Ok((
        IBig::from_str_radix(cos, 16).expect("immutable actual anchor hexadecimal"),
        IBig::from_str_radix(sin, 16).expect("immutable actual anchor hexadecimal"),
    ))
}

/// x/2^P должен лежать в [0,π/2); dyadic domain проверяется точно.
/// Source floor-деления и floor-сдвиги сохраняют отрицательный Taylor-tail.
pub fn cos_sin_basecase(x: &IBig, bits: u32) -> BasecaseResult<(IBig, IBig)> {
    if !(MIN_FIXED_PRECISION_BITS..=MAX_FIXED_PRECISION_BITS).contains(&bits) {
        return Err(BasecaseError::UnsupportedProfile(
            UnsupportedProfile::Precision {
                requested: bits,
                minimum: MIN_FIXED_PRECISION_BITS,
                maximum: MAX_FIXED_PRECISION_BITS,
            },
        ));
    }
    let maximum = IBig::from(pi_fixed(bits - 1).map_err(BasecaseError::Pi)?);
    if x < &IBig::ZERO || x > &maximum {
        return Err(BasecaseError::UnsupportedProfile(
            UnsupportedProfile::ReducedArgument {
                requested: x.clone(),
                minimum: IBig::ZERO,
                maximum,
                bits,
            },
        ));
    }
    let cell_bits = (bits - 8) as usize;
    let cell = x >> cell_bits;
    let index = u32::try_from(&cell).expect("domain даёт anchor index 0..402");
    let (cos_t, sin_t) = anchor(index)?;
    let offset = (ANCHOR_CACHE_PRECISION_BITS - bits) as usize;
    let cos_t = cos_t >> offset;
    let sin_t = sin_t >> offset;
    let residual = x - (cell << cell_bits);
    let mut cos = IBig::ONE << bits as usize;
    let mut sin = residual.clone();
    let mut k = 2u32;
    let mut a = -floor_shift(&(&residual * &residual), bits as usize);
    while !a.is_zero() {
        a = floor_div(&a, &IBig::from(k));
        cos += &a;
        k += 1;
        a = floor_shift(&(&a * &residual), bits as usize);
        a = floor_div(&a, &IBig::from(k));
        sin += &a;
        k += 1;
        a = -floor_shift(&(&a * &residual), bits as usize);
    }
    Ok((
        floor_shift(&(&cos * &cos_t - &sin * &sin_t), bits as usize),
        floor_shift(&(&sin * &cos_t + &cos * &sin_t), bits as usize),
    ))
}

use crate::legacy_fixed::{floor_div, floor_shift};

#[cfg(test)]
mod tests {
    use super::{floor_div, floor_shift};
    use crate::IBig;

    #[test]
    fn signed_tail_rounding_is_floor_for_division_and_shift() {
        for (n, d, expected) in [(-1, 2, -1), (-5, 3, -2), (-6, 3, -2), (5, 3, 1)] {
            assert_eq!(
                floor_div(&IBig::from(n), &IBig::from(d)),
                IBig::from(expected)
            );
        }
        assert_eq!(floor_shift(&IBig::from(-3), 1), IBig::from(-2));
        assert_eq!(floor_shift(&IBig::from(-4), 1), IBig::from(-2));
        assert_eq!(floor_shift(&IBig::from(-1), 400), IBig::from(-1));
    }
}

